"""NAVSIM agent that reads token-named trajectories generated by GPUDrive."""

from pathlib import Path

import numpy as np
from nuplan.planning.simulation.trajectory.trajectory_sampling import TrajectorySampling

from navsim.agents.abstract_agent import AbstractAgent
from navsim.common.dataclasses import AgentInput, SensorConfig, Trajectory


class OfflineTrajectoryAgent(AbstractAgent):
    """Return a precomputed local trajectory for each evaluation token."""

    def __init__(
        self,
        trajectory_dir: str,
        trajectory_sampling: TrajectorySampling = TrajectorySampling(time_horizon=4, interval_length=0.5),
    ):
        super().__init__(trajectory_sampling)
        self._trajectory_dir = Path(trajectory_dir)

    def name(self) -> str:
        return self.__class__.__name__

    def get_sensor_config(self) -> SensorConfig:
        return SensorConfig.build_no_sensors()

    def initialize(self) -> None:
        if not self._trajectory_dir.is_dir():
            raise FileNotFoundError(f"Trajectory directory does not exist: {self._trajectory_dir}")

    def compute_trajectory(self, agent_input: AgentInput, token: str) -> Trajectory:
        del agent_input
        path = self._trajectory_dir / f"{token}.npy"
        if not path.is_file():
            raise FileNotFoundError(f"Offline trajectory not found for token {token}: {path}")

        poses = np.load(path, allow_pickle=False).astype(np.float32, copy=False)
        expected_shape = (self._trajectory_sampling.num_poses, 3)
        if poses.shape != expected_shape:
            raise ValueError(f"Trajectory {path} has shape {poses.shape}; expected {expected_shape}")
        if not np.isfinite(poses).all():
            raise ValueError(f"Trajectory contains non-finite values: {path}")
        return Trajectory(poses, self._trajectory_sampling)
